#!/bin/sh
# Render the Arch Linux PKGBUILD (AUR package "sealctl-bin") from release tarballs.
#   scripts/render-pkgbuild.sh <version> <base-url> <dist-dir>
# With <base-url> = "local" the sources are plain file names (for testing with makepkg).
set -eu
VERSION="$1"; BASE="$2"; DIST="$3"
sha() { cut -d' ' -f1 "$DIST/sealctl-$VERSION-$1.tar.gz.sha256"; }
src() {
  if [ "$BASE" = local ]; then echo "sealctl-$VERSION-$1.tar.gz"
  else echo "sealctl-$VERSION-$1.tar.gz::$BASE/sealctl-$VERSION-$1.tar.gz"; fi
}
cat <<EOF
# Maintainer: Oleksiy Pylypenko
# Generated by sealctl's release workflow (scripts/render-pkgbuild.sh).
pkgname=sealctl-bin
pkgver=$VERSION
pkgrel=1
pkgdesc="Phone-approved keys: secrets kept from AI agents, SSH, git signing, volumes, backups"
arch=('x86_64' 'aarch64')
url="https://github.com/sealctl/sealctl"
license=('MIT')
depends=('gcc-libs' 'glibc')
optdepends=('restic: encrypted backups'
            'cryptsetup: encrypted LUKS volumes'
            'openssh: SSH agent and git signing')
provides=('sealctl')
conflicts=('sealctl')
options=('!strip' '!debug')
source_x86_64=("$(src x86_64-unknown-linux-gnu)")
sha256sums_x86_64=('$(sha x86_64-unknown-linux-gnu)')
source_aarch64=("$(src aarch64-unknown-linux-gnu)")
sha256sums_aarch64=('$(sha aarch64-unknown-linux-gnu)')

package() {
  cd "\$srcdir"/sealctl-"\$pkgver"-*/
  install -Dm755 sealctl "\$pkgdir/usr/bin/sealctl"
  install -Dm644 LICENSE "\$pkgdir/usr/share/licenses/\$pkgname/LICENSE"
  install -Dm644 THIRD-PARTY-NOTICES.md "\$pkgdir/usr/share/licenses/\$pkgname/THIRD-PARTY-NOTICES.md"
  install -Dm644 README.md "\$pkgdir/usr/share/doc/\$pkgname/README.md"
  install -Dm644 completions/sealctl.bash "\$pkgdir/usr/share/bash-completion/completions/sealctl"
  install -Dm644 completions/_sealctl "\$pkgdir/usr/share/zsh/site-functions/_sealctl"
  install -Dm644 completions/sealctl.fish "\$pkgdir/usr/share/fish/vendor_completions.d/sealctl.fish"
}
EOF
